const calendarResponse = $input.first().json;
const events = (calendarResponse.items || []).map(e => ({
  start: new Date(e.start.dateTime || e.start.date),
  end: new Date(e.end.dateTime || e.end.date)
}));

// Berliner Feiertage (feste + bewegliche via Gauss-Osterformel)
function getBerlinHolidays(year) {
  const holidays = [
    `${year}-01-01`,`${year}-03-08`,`${year}-05-01`,
    `${year}-10-03`,`${year}-12-25`,`${year}-12-26`,
  ];
  const a=year%19,b=Math.floor(year/100),c=year%100;
  const d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25);
  const g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30;
  const i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7;
  const m=Math.floor((a+11*h+22*l)/451);
  const mo=Math.floor((h+l-7*m+114)/31);
  const da=((h+l-7*m+114)%31)+1;
  const easter=new Date(year,mo-1,da);
  const add=(d,n)=>{const r=new Date(d);r.setDate(r.getDate()+n);return r;};
  const fmt=(d)=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
  [-2,1,39,50].forEach(o=>holidays.push(fmt(add(easter,o))));
  return new Set(holidays);
}

const now=new Date();
const nowBerlin=new Date(now.toLocaleString('en-US',{timeZone:'Europe/Berlin'}));
const holidays=getBerlinHolidays(nowBerlin.getFullYear());
getBerlinHolidays(nowBerlin.getFullYear()+1).forEach(h=>holidays.add(h));

const allSlots=[];
const slotDuration=20;
const maxSlots=10;
const maxSlotsPerDay=3;
const maxDays=30;
const dayNames=['Sonntag','Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag'];
const monthNames=['Januar','Februar','März','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember'];

// Schritt 1: Alle verfügbaren Slots über 30 Tage sammeln (max 3 pro Tag)
for(let dayOffset=0;dayOffset<maxDays;dayOffset++){
  const checkDate=new Date(nowBerlin);
  checkDate.setDate(checkDate.getDate()+dayOffset);
  checkDate.setHours(0,0,0,0);

  const wd=checkDate.getDay();
  if(wd===0||wd===6) continue;

  const dateKey=checkDate.getFullYear()+'-'+String(checkDate.getMonth()+1).padStart(2,'0')+'-'+String(checkDate.getDate()).padStart(2,'0');
  if(holidays.has(dateKey)) continue;

  const displayDate=dayNames[wd]+', '+checkDate.getDate()+'. '+monthNames[checkDate.getMonth()];
  let slotsToday=0;

  for(let hour=9;hour<18&&slotsToday<maxSlotsPerDay;hour++){
    for(let minute=0;minute<60&&slotsToday<maxSlotsPerDay;minute+=slotDuration){
      const slotBerlin=new Date(checkDate);
      slotBerlin.setHours(hour,minute,0,0);
      const slotEndBerlin=new Date(slotBerlin);
      slotEndBerlin.setMinutes(slotEndBerlin.getMinutes()+slotDuration);

      const endLimit=new Date(checkDate);
      endLimit.setHours(17,30,0,0);
      if(slotEndBerlin>endLimit) continue;
      if(slotBerlin<=nowBerlin) continue;

      const isoStart=dateKey+'T'+String(hour).padStart(2,'0')+':'+String(minute).padStart(2,'0')+':00+02:00';
      const endH=slotEndBerlin.getHours();
      const endM=slotEndBerlin.getMinutes();
      const isoEnd=dateKey+'T'+String(endH).padStart(2,'0')+':'+String(endM).padStart(2,'0')+':00+02:00';
      const startUTC=new Date(isoStart);
      const endUTC=new Date(isoEnd);

      const hasConflict=events.some(ev=>startUTC<ev.end&&endUTC>ev.start);
      if(!hasConflict){
        allSlots.push({
          date:displayDate,
          time:String(hour).padStart(2,'0')+':'+String(minute).padStart(2,'0'),
          slot_id:isoStart
        });
        slotsToday++;
      }
    }
  }
}

// Schritt 2: Auf maxSlots begrenzen (bereits über Tage verteilt durch maxSlotsPerDay)
const result=allSlots.slice(0,maxSlots);
return [{json:{slots:result,count:result.length}}];
